  background:
    radial-gradient(110% 85% at 50% 50%,transparent 38%,rgba(60,42,20,.55) 80%,rgba(20,12,4,.92) 120%),
    repeating-linear-gradient(to bottom,rgba(255,236,190,.06) 0 2px,transparent 2px 5px);
  mix-blend-mode:normal; }
