  background:radial-gradient(circle at 50% 50%,var(--gold-hot) 0 22%,#8a5a22 24% 34%,transparent 36%),
    conic-gradient(from 0deg,var(--gold),#7a4e18,var(--gold-hot),#7a4e18,var(--gold));
