/* ===== custom properties ============================================== */
:root{
  --f-display:'Rajdhani','Bahnschrift SemiCondensed','Bahnschrift','Barlow Condensed','Segoe UI Variable Display','Segoe UI Semibold','Segoe UI',system-ui,sans-serif;
  --f-body:'Segoe UI Variable Text','Segoe UI','Avenir Next','Avenir','Trebuchet MS','Nunito','Quicksand',system-ui,-apple-system,sans-serif;
  --f-num:'Rajdhani','Bahnschrift','Segoe UI Variable Display','Segoe UI','DIN Alternate',system-ui,sans-serif;

  --accent:#7fd8a8;
  --accent-dim:#2e6a4c;
  --accent-hot:#d6ffe9;
  --accent-glow:rgba(127,216,168,.5);
  --accent-ink:#08170f;

  --gold:#e9c36b;
  --gold-hot:#fff1c2;
  --gold-dim:#8a6a2c;
  --gold-glow:rgba(233,195,107,.45);
  --gold-ink:#2a1d08;

  --safe:#8ef0b8;
  --danger:#ff5f4a;
  --cp:#7fe6ff;
  --crest:#ffd166;
  --sigil:#c98bff;
  --coin:#ffcf5c;
  --ahead:#8ef0b8;
  --behind:#ff7a66;

  --ink:#f7eedb;
  --ink-dim:#cbbca0;
  --ink-mute:#8c7f6a;
  --ink-ghost:rgba(247,238,219,.30);
  --void:#0b0a16;
  --parch:#f3e9d2;

  /* parchment-tinted frosted glass: a warm plum ground so text reads over any
     realm, with a cream lift at the top edge so it reads as glass on paper */
  --glass:linear-gradient(162deg,rgba(84,66,74,.62) 0%,rgba(46,34,56,.74) 46%,rgba(30,22,42,.82) 100%);
  --glass-flat:rgba(40,30,48,.76);
  --glass-lift:linear-gradient(180deg,rgba(243,233,210,.16),rgba(243,233,210,.03) 38%,transparent 60%);
  --stroke:rgba(233,195,107,.34);
  --stroke-hi:rgba(233,195,107,.62);
  --hair:rgba(243,233,210,.10);
  --hair-soft:rgba(243,233,210,.06);

  --r-xs:3px; --r-sm:6px; --r-md:10px;
  --r-lg:16px; --r-xl:22px; --r-pill:999px;

  --e-out:cubic-bezier(.16,.84,.34,1);
  --e-in:cubic-bezier(.5,0,.9,.32);
  --e-io:cubic-bezier(.62,.02,.24,1);
  --e-spring:cubic-bezier(.2,1.5,.36,1);
  --e-snap:cubic-bezier(.08,.82,.17,1);

  --oct:polygon(29% 0,71% 0,100% 29%,100% 71%,71% 100%,29% 100%,0 71%,0 29%);
  --hud-scale:1;
  --ui-fade:1;
}

